// GitHub emoji shortcode lookup (":rocket:" -> U+1F680).
//
// The data lives in emoji_table.inc, generated by scripts/gen_emoji.py from
// GitHub's gemoji database. All tables are constexpr and pointer-free, so
// they are constant-initialized into read-only data: no dynamic
// initialization, no relocations. Lookup is a binary search over names
// sorted byte-wise; it never allocates and never throws.

#include "emoji.h"

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <iterator>

namespace mdv {
namespace {

#include "emoji_table.inc"

constexpr std::string_view NameOf(const EmojiEntry& e) noexcept {
  return {kEmojiNames + e.name_off, e.name_len};
}

}  // namespace

std::wstring_view LookupEmojiShortcode(std::string_view name) {
  if (name.empty() || name.size() > kEmojiMaxNameLen) return {};
  const EmojiEntry* first = std::begin(kEmojiEntries);
  const EmojiEntry* last = std::end(kEmojiEntries);
  const EmojiEntry* it = std::lower_bound(
      first, last, name,
      [](const EmojiEntry& e, std::string_view key) noexcept { return NameOf(e) < key; });
  if (it == last || NameOf(*it) != name) return {};
  return {kEmojiChars + it->emoji_off, it->emoji_len};
}

}  // namespace mdv
